files.agent-pane/theme.css:
/* Tonal's chat: flat, opaque, tonal. Depth comes from how strongly a surface is tinted by the
   theme's one accent (its seed), never from a shadow or a frost: the page is the lowest surface,
   cards sit one tone up, the composer and its hat one more, menus the highest. Corners follow one
   scale: 12 px for small controls and inline pieces, 16 px for cards and the prompt bubble, 28 px
   for the composer, the sheet-sized surface you type into. Hover and press are state layers: the
   ink laid over its container at 8% and 12%, the same two steps everywhere. Lines are a quiet
   1 px outline in the ink at 12%, drawn only where tone alone can't tell two surfaces apart.
   Every color is mixed from the theme's own (--agent-accent, --agent-text, --agent-page-bg), so
   this one file reads over Tonal and Tonal Dark, and over any theme of your own.
   Paint only, on :root: nothing in the transcript moves when this applies or reloads.
   The tones, as used below: the seed over the page at 4% (low), 10% (high) and 14% (highest)
   for containers; at 18% for the secondary container (your prompt); the ink at 12% for
   the outline; the ink at 8% for hover and 12% for press. */
:root {
  /* ---------- Text ----------
     Body text stays the theme's; the secondary level a clear step down, the quietest a step
     further, both still readable. Headings keep the body color; their weight is the type scale's. */
  --cv-text-muted: color-mix(in srgb, var(--agent-text) 70%, transparent);
  --cv-text-dim: color-mix(in srgb, var(--agent-text) 58%, transparent);
  --cv-activity-text: color-mix(in srgb, var(--agent-text) 64%, transparent);
  --cv-heading-text: var(--agent-text);
  /* Links in the seed, pulled a little toward the ink so they hold contrast on every surface. */
  --cv-link: color-mix(in srgb, var(--agent-accent) 82%, var(--agent-text));
  --agent-link: color-mix(in srgb, var(--agent-accent) 82%, var(--agent-text));

  /* ---------- The prompt bubble ----------
     Your prompt in the secondary container: a solid tone, no edge, the card corner. */
  --cv-user-bubble-tint: color-mix(in srgb, var(--agent-accent) 18%, var(--agent-page-bg));
  --cv-user-bubble-edge: transparent;
  --cv-user-bubble-radius: 16px;

  /* ---------- Cards ----------
     Tool output, code, edits and plans one tone up from the page, 16 px corners, and the quiet
     outline so a card still reads on a page of the same hue. Inline code is a small control's
     piece: the low container, a small corner. The reply stays plain text, no card. */
  --cv-card-fill: color-mix(in srgb, var(--agent-accent) 4%, var(--agent-page-bg));
  --cv-card-ring: color-mix(in srgb, var(--agent-text) 12%, transparent);
  --cv-card-radius: 16px;
  --cv-code-fill: color-mix(in srgb, var(--agent-accent) 10%, var(--agent-page-bg));
  --cv-code-radius: 6px;
  --cv-reply-fill: transparent;
  --cv-reply-ring: transparent;

  /* ---------- Hover ----------
     A state layer arrives quickly and evenly; Reduce Motion keeps it instant. */
  --cv-hover-duration: 120ms;
  --cv-hover-ease: cubic-bezier(0.2, 0, 0, 1);

  /* ---------- The composer and its hat ----------
     The composer is the page's largest control: an opaque container two tones up, 28 px corners,
     the quiet outline, and no shadow (its tone lifts it). The hat over it (the running work, the
     goal) is one tone higher and rounds on the card scale, so it reads as a lid, not a second box. */
  --cmux-composer-fill: color-mix(in srgb, var(--agent-accent) 10%, var(--agent-page-bg));
  --cmux-composer-border: color-mix(in srgb, var(--agent-text) 12%, transparent);
  --cmux-composer-shadow: 0 0 transparent;
  --cmux-composer-radius: 28px;
  --cmux-composer-hat-fill: color-mix(in srgb, var(--agent-accent) 14%, var(--agent-page-bg));
  --cmux-composer-hat-radius: 16px;

  /* ---------- Menus, pickers and popovers ----------
     The highest container, opaque, 12 px corners, the quiet outline. The highlighted row is the
     hover state layer, concentric with the panel. */
  --cv-popover-fill: color-mix(in srgb, var(--agent-accent) 14%, var(--agent-page-bg));
  --cv-popover-ring: color-mix(in srgb, var(--agent-text) 12%, transparent);
  --cv-popover-radius: 12px;
  --cv-popover-row-selected: color-mix(in srgb, var(--agent-text) 8%, transparent);

  /* The same for the shared menus (--menu-*): a 4 px inset, 32 px rows, an 8 px row highlight
     inside the 12 px panel, labels at the label size, separators full width as hairlines. */
  --menu-radius: 12px;
  --menu-padding: 4px;
  --menu-fill: color-mix(in srgb, var(--agent-accent) 14%, var(--agent-page-bg));
  --menu-border: color-mix(in srgb, var(--agent-text) 12%, transparent);
  --menu-row-height: 32px;
  --menu-hover-fill: color-mix(in srgb, var(--agent-text) 8%, transparent);
  --menu-hover-radius: 8px;
  --menu-separator: color-mix(in srgb, var(--agent-text) 12%, transparent);
  --menu-separator-inset: 0px;
  --menu-label-color: var(--cv-text-muted);
  --menu-label-weight: 500;
  --menu-label-size: var(--text-caption);
  --menu-shortcut-color: var(--cv-text-dim);
  --menu-subtitle-color: var(--cv-text-muted);
  --menu-disabled-opacity: 0.38;
  --menu-submenu-offset: -4px;
  --menu-submenu-align-offset: -4px;

  /* ---------- The toast ----------
     The app's toast is drawn by the app, not this page, so no stylesheet reaches it: Tonal's calm
     toast (a 12 px tonal card on the inverse surface, not a pill, not glass) comes with the
     notifications.toast.style key's flat style, pending. */
}

/* ---------- Buttons in the composer ----------
   No token reaches these yet, so they are styled by the composer's own classes; they change paint
   only, never a size, so the composer's rows keep their heights.
   Secondary controls (the pickers and chips) are tonal: the secondary container at rest, the state
   layers over it. Icon buttons hover with the 8% layer over the composer's own fill. */
:root .acpmux-shell {
  --acpmux-pill-fill: color-mix(in srgb, var(--agent-accent) 18%, var(--agent-page-bg));
  --acpmux-pill-hover: color-mix(
    in srgb,
    var(--agent-text) 8%,
    color-mix(in srgb, var(--agent-accent) 18%, var(--agent-page-bg))
  );
  --acpmux-pill-open: color-mix(
    in srgb,
    var(--agent-text) 12%,
    color-mix(in srgb, var(--agent-accent) 18%, var(--agent-page-bg))
  );
  --acpmux-pill-press: color-mix(
    in srgb,
    var(--agent-text) 12%,
    color-mix(in srgb, var(--agent-accent) 18%, var(--agent-page-bg))
  );
  --acpmux-pill-edge: transparent;
  --acpmux-composer-hover: color-mix(
    in srgb,
    var(--agent-text) 8%,
    color-mix(in srgb, var(--agent-accent) 10%, var(--agent-page-bg))
  );
  /* The cards over the composer (a folder question, a secret) sit on the highest container. */
  --acpmux-composer-tray: color-mix(in srgb, var(--agent-accent) 14%, var(--agent-page-bg));
}
:root .acpmux-composer-box .acpmux-picker-button {
  border-radius: 12px;
}

/* Send is the one prominent action: once there is something to send, a filled container in the
   accent with the accent's ink, its corner a 12 px rounded square rather than a disc. Hover and
   press lay the ink over it at 8% and 12%. Empty, it rests as a quiet tonal square; Stop is tonal
   too, so only a sendable prompt carries the accent. */
:root .acpmux-composer-box .acpmux-send {
  border-radius: 12px;
}
:root .acpmux-composer-box .acpmux-send.acpmux-cancel {
  background: color-mix(in srgb, var(--agent-accent) 18%, var(--agent-page-bg));
  color: var(--agent-text);
}
:root .acpmux-composer-box .acpmux-send.acpmux-send-ready:not(.acpmux-cancel):not(:disabled) {
  background: var(--agent-accent);
  color: var(--agent-accent-text, var(--agent-page-bg));
}
@media (hover: hover) and (pointer: fine) {
  :root .acpmux-composer-box .acpmux-send.acpmux-send-ready:not(.acpmux-cancel):not(:disabled):hover {
    background: color-mix(in srgb, var(--agent-accent-text, var(--agent-page-bg)) 8%, var(--agent-accent));
  }
}
:root .acpmux-composer-box .acpmux-send.acpmux-send-ready:not(.acpmux-cancel):not(:disabled):active {
  background: color-mix(in srgb, var(--agent-accent-text, var(--agent-page-bg)) 12%, var(--agent-accent));
}

files.markdown/theme.css:
/* Tonal's Markdown viewer: the chat's tonal surfaces on a page. Code sits in a container one tone
   up, tinted by the theme's accent (its seed), with the card corner (16 px); tables take the same
   container for their header row and the quiet outline for their lines; headings carry no rule,
   their weight does the work; a quote hangs on a 4 px bar in the seed; popovers are opaque and
   lifted by tone, not by a shadow.
   Only --cmux-md-* custom properties on :root; every color is mixed from the page's own, so this
   one file reads over the light and the dark theme file alike. */
:root {
  --cmux-md-code-background: color-mix(in srgb, var(--cmux-accent, var(--page-text)) 7%, var(--page-elevated));
  --cmux-md-code-radius: 16px;
  --cmux-md-border-color: color-mix(in srgb, var(--page-text) 12%, transparent);
  --cmux-md-heading-weight: 600;
  --cmux-md-heading-rule: none;
  --cmux-md-quote-border: 4px solid color-mix(in srgb, var(--cmux-accent, var(--page-text)) 60%, transparent);
  --cmux-md-table-border: 1px solid var(--cmux-md-border-color);
  --cmux-md-table-header-background: color-mix(in srgb, var(--cmux-accent, var(--page-text)) 10%, var(--page-elevated));
  --cmux-md-accent-background: color-mix(in srgb, var(--cmux-accent, var(--page-text)) 12%, transparent);
  --cmux-md-popover-background: color-mix(in srgb, var(--cmux-accent, var(--page-text)) 14%, var(--page-elevated));
  --cmux-md-popover-shadow: 0 0 0 1px var(--cmux-md-border-color);
}
